def get_valid_operator():
    """Get a valid operator from user input."""
    while True:
        operator = input("Please enter an operator (+, -, *, /): ").strip()
        if operator in ['+', '-', '*', '/']:
            return operator
        else:
            print("Invalid operator. Please try again.")

def perform_operation(num1, num2, operator):
    """Perform the specified operation on two numbers."""
    if operator == '+':
        return num1 + num2
    elif operator == '-':
        return num1 - num2
    elif operator == '*':
        return num1 * num2
    elif operator == '/':
        if num2 == 0:
            return "Error: Division by zero. Please try again."
        else:
            return num1 / num2
    else:
        return "Error: Invalid operator. Please try again."

if __name__ == "__main__":
    try:
        num1 = float(input("Enter the first number: "))
        operator = get_valid_operator()
        num2 = float(input(f"Enter the second number for {operator}: "))
        result = perform_operation(num1, num2, operator)
        print(f"{num1} {operator} {num2} = {result}")
    except ValueError:
        print("Error: Invalid input. Please try again.")
```

This program will keep prompting the user for input until they enter a valid operator. It will also handle division by zero errors and provide clear error messages for invalid inputs.
